import {createHash} from 'node:crypto';import {lstat,readFile,realpath} from 'node:fs/promises';import path from 'node:path';
export const REQUIRED_RECOVERY_FILES=['authoring.json','services.json','operations.json','assets.json','workspace-profile.json','cue-baseline.json','source-library.json','authoring-sources.json','legacy-source-map.json'];
const samePath=(a,b)=>process.platform==='win32'?a.toLowerCase()===b.toLowerCase():a===b;
export async function verifyRecoveryBundle(directory){const base=await realpath(path.resolve(directory)),manifestPath=path.join(base,'manifest.json'),manifestStat=await lstat(manifestPath);if(manifestStat.isSymbolicLink()||!manifestStat.isFile())throw new Error('Manifest must be a regular file.');const manifest=JSON.parse(await readFile(manifestPath,'utf8'));if(manifest.format!=='crc-overlays-recovery'||manifest.version!==1||!Array.isArray(manifest.contents)||!manifest.contents.length)throw new Error('Unsupported or empty recovery bundle.');for(const item of manifest.contents)if(typeof item?.name!=='string'||item.name.includes('..')||path.isAbsolute(item.name)||!/^[-a-zA-Z0-9._/]+$/.test(item.name)||!Number.isSafeInteger(item.bytes)||item.bytes<=0||!/^[a-f0-9]{64}$/.test(item.sha256))throw new Error('Unsafe recovery manifest entry.');const names=manifest.contents.map(item=>item.name);if(new Set(names).size!==names.length)throw new Error('Recovery manifest contains duplicate file names.');for(const required of REQUIRED_RECOVERY_FILES)if(!names.includes(required))throw new Error(`Recovery manifest is missing ${required}.`);const files=new Map();for(const item of manifest.contents){const expected=path.resolve(base,item.name),fileStat=await lstat(expected);if(fileStat.isSymbolicLink()||!fileStat.isFile())throw new Error(`Recovery item is not a regular file: ${item.name}`);const actual=await realpath(expected);if(!samePath(actual,expected)||!actual.startsWith(base+path.sep))throw new Error(`Recovery item escapes its bundle: ${item.name}`);const content=await readFile(actual);if(content.length!==item.bytes||createHash('sha256').update(content).digest('hex')!==item.sha256)throw new Error(`Checksum failed: ${item.name}`);if(item.name.endsWith('.json'))JSON.parse(content.toString('utf8'));files.set(item.name,content)}return {manifest,files}}
